pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        // admin is the deployer of C, i.e. this test contract
        address admin = address(this);
        vm.assume(newOwner != admin);
        vm.prank(admin);
        c.setOwner(newOwner);
        assertTrue(c.owner() == newOwner, "owner must be the requested new owner");
    }
}
